//! Model-based test: replay traces of `spec/product_registry.qnt` against a
//! real `DaemonDispatch` and check, after every step, that the daemon's live
//! registration cache and request outcomes match the model.
//!
//! The traces are generated by `spec/regen_traces.sh` and committed under
//! `tests/fixtures/product_registry_mbt/`. CI does not need Quint.
//!
//! This replaces hand-written scenario tests for create → bind → restart and
//! damaged-binding hydration (bicameral#65): the model checks the same
//! properties as invariants over every generated sequence, and this driver
//! checks that the Rust code takes the same steps.

use super::*;
use crate::project_registry::{
    FileProjectRegistrationStore, ProjectEventStoreRouter, ProjectRegistrationStore,
    ProjectRegistryError, ProjectRouteRecord,
};
use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};

// ── Test-owned registry store whose `list()` can be made to fail ───────────

struct FlakyListStore {
    inner: FileProjectRegistrationStore,
    list_fails: AtomicBool,
}

impl ProjectRegistrationStore for FlakyListStore {
    fn get(
        &self,
        product_id: &str,
        cloud_account_id: &str,
    ) -> Result<Option<ProjectRouteRecord>, ProjectRegistryError> {
        self.inner.get(product_id, cloud_account_id)
    }

    fn list(&self) -> Result<Vec<ProjectRouteRecord>, ProjectRegistryError> {
        if self.list_fails.load(Ordering::SeqCst) {
            return Err(ProjectRegistryError::Io("injected list failure".into()));
        }
        self.inner.list()
    }

    fn write(&self, record: &ProjectRouteRecord) -> Result<(), ProjectRegistryError> {
        self.inner.write(record)
    }
}

// ── Model state decoded from ITF ───────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct ModelEntry {
    has_binding: bool,
    setup: String,
}

#[derive(Debug)]
struct ModelState {
    durable: BTreeSet<String>,
    cache: BTreeMap<String, ModelEntry>,
    list_fails: bool,
    last_action: String,
    last_product: String,
}

fn decode_state(raw: &serde_json::Value) -> ModelState {
    // Quint prefixes every variable with its module path; keep the last segment.
    let vars: BTreeMap<&str, &serde_json::Value> = raw
        .as_object()
        .expect("ITF state is an object")
        .iter()
        .filter(|(key, _)| !key.starts_with('#'))
        .map(|(key, value)| (key.rsplit("::").next().unwrap(), value))
        .collect();
    let string = |name: &str| vars[name].as_str().expect(name).to_string();
    let durable = vars["durable"]["#set"]
        .as_array()
        .expect("durable is a set")
        .iter()
        .map(|p| p.as_str().unwrap().to_string())
        .collect();
    let cache = vars["cache"]["#map"]
        .as_array()
        .expect("cache is a map")
        .iter()
        .map(|pair| {
            let product = pair[0].as_str().unwrap().to_string();
            let setup = match pair[1]["setup"]["tag"].as_str().unwrap() {
                "Normal" => "normal",
                "RepairRequired" => "local_workspace_repair_required",
                "GroundingNotReady" => "code_grounding_not_ready",
                other => panic!("unknown Setup tag {other}"),
            };
            let entry = ModelEntry {
                has_binding: pair[1]["hasBinding"].as_bool().unwrap(),
                setup: setup.to_string(),
            };
            (product, entry)
        })
        .collect();
    ModelState {
        durable,
        cache,
        list_fails: vars["listFails"].as_bool().expect("listFails"),
        last_action: string("lastAction"),
        last_product: string("lastProduct"),
    }
}

// ── System under test ──────────────────────────────────────────────────────

struct Harness {
    _home: tempfile::TempDir,
    _workspace: tempfile::TempDir,
    workspace: PathBuf,
    events_dir: PathBuf,
    bindings_dir: PathBuf,
    store: Arc<FlakyListStore>,
    dispatch: DaemonDispatch,
    /// model product id → real product id (learned from product.create)
    real_ids: BTreeMap<String, String>,
    candidates: BTreeMap<String, tempfile::TempDir>,
}

impl Harness {
    fn new() -> Self {
        let home = tempfile::tempdir().unwrap();
        let workspace = tempfile::tempdir().unwrap();
        let events_dir = workspace.path().join(".bicameral/events");
        let bindings_dir = home.path().join("workspace-bindings");
        let store = Arc::new(FlakyListStore {
            inner: FileProjectRegistrationStore::new(home.path().join("projects")),
            list_fails: AtomicBool::new(false),
        });
        let dispatch = Self::daemon(&store, &events_dir, &bindings_dir, Vec::new());
        Self {
            workspace: workspace.path().to_path_buf(),
            _home: home,
            _workspace: workspace,
            events_dir,
            bindings_dir,
            store,
            dispatch,
            real_ids: BTreeMap::new(),
            candidates: BTreeMap::new(),
        }
    }

    fn daemon(
        store: &Arc<FlakyListStore>,
        events_dir: &Path,
        bindings_dir: &Path,
        registrations: Vec<LocalProjectRegistration>,
    ) -> DaemonDispatch {
        let store: Arc<dyn ProjectRegistrationStore> = store.clone();
        DaemonDispatch {
            adapter: Arc::new(crate::event_store_adapters::GitAdapter::new(events_dir)),
            operator_scoped: false,
            project_router: Some(Arc::new(ProjectEventStoreRouter::new(store))),
            current_event_store_route: Some(crate::project_registry::EventStoreRoute::Git {
                events_dir: events_dir.to_path_buf(),
                ci_merge_gate_configured: false,
            }),
            commit_watcher: crate::commit_watcher::CommitWatcherStore::default(),
            product_commit_watchers: crate::commit_watcher::ProductCommitWatcherStore::default(),
            capability_readiness: None,
            operational_logs: None,
            workspace_bindings_dir: Some(bindings_dir.to_path_buf()),
            project_registrations: Arc::new(std::sync::RwLock::new(registrations)),
            product_join_trust: None,
            confirmation_challenges: Arc::new(
                crate::confirmation_challenge_store::ConfirmationChallengeStore::new(),
            ),
            candidate_selection_authority: super::test_selection_fields().0,
            product_currentness: super::test_selection_fields().1,
            candidate_selection: super::test_selection_fields().2,
            atomic_adapter: super::test_selection_fields().3,
            projection_work_store: super::test_projection_work_store("registry-mbt"),
            candidates: Arc::new(tokio::sync::RwLock::new(std::collections::HashMap::new())),
            reviews: Arc::new(tokio::sync::RwLock::new(std::collections::HashMap::new())),
            proof_signer: None,
        }
    }

    /// Real id for a model product. Products never created get a stable id
    /// that is guaranteed not to be registered.
    fn real_id(&self, product: &str) -> String {
        self.real_ids
            .get(product)
            .cloned()
            .unwrap_or_else(|| format!("prd_mbt_never_created_{product}"))
    }

    fn create(&mut self, product: &str) -> ToolResponse {
        let request = ToolRequest::new(
            ToolCommand::ProductCreate(ProductCreateParams {
                idempotency_key: format!("mbt-create-{product}"),
                product_display_name: format!("MBT {product}"),
                event_store_descriptor: None,
                asserted_cloud_account_id: Some("acct_route".into()),
                team_display_name: None,
                verified_domain: None,
                event_store_hint: None,
                required_connection: None,
            }),
            super::hosted_route_authority(),
        );
        let response = self.dispatch.dispatch(&request, Some(&self.workspace));
        if let Some(id) = response
            .result
            .as_ref()
            .and_then(|r| r["result"]["product_id"].as_str())
        {
            let previous = self.real_ids.insert(product.into(), id.into());
            assert!(
                previous.is_none_or(|p| p == id),
                "idempotent retry of product.create returned a different product id"
            );
        }
        response
    }

    fn bind(&mut self, product: &str) -> ToolResponse {
        let candidate = self
            .candidates
            .entry(product.into())
            .or_insert_with(|| tempfile::tempdir().unwrap())
            .path()
            .to_path_buf();
        let request = ToolRequest::new(
            ToolCommand::WorkspaceBind(WorkspaceBindRequest {
                proposal: WorkspaceBindingProposal {
                    project_id: self.real_id(product),
                    display: ProjectSafeDisplayMetadata {
                        display_name: format!("MBT {product}"),
                        project_slug: None,
                        candidate_label: None,
                    },
                    candidate_path: candidate.display().to_string(),
                    source_surface: WorkspaceBindingSourceSurface::Mcp,
                    reason: "operator confirmed".to_string(),
                    confidence: 1.0,
                },
                confirmed: true,
                required_daemon_capability: Some(DAEMON_WORKSPACE_BINDING_CAPABILITY),
                expected_current_state: Some(WorkspaceBindingState::LocalWorkspaceUnbound),
            }),
            bicameral_api::fixtures::authority_mcp("agent-mbt", "session-mbt", "/workspace"),
        );
        self.dispatch.dispatch(&request, Some(&candidate))
    }

    fn restart(&mut self) {
        let router = self.dispatch.project_router.clone().unwrap();
        let registrations = hydrate_project_registrations(&router, Some(&self.bindings_dir));
        self.dispatch = Self::daemon(
            &self.store,
            &self.events_dir,
            &self.bindings_dir,
            registrations,
        );
    }

    fn corrupt_binding(&self, product: &str) {
        let id = self.real_id(product);
        assert!(
            id.chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.')),
            "binding file name would be sanitized: {id}"
        );
        std::fs::create_dir_all(&self.bindings_dir).unwrap();
        std::fs::write(self.bindings_dir.join(format!("{id}.json")), b"not-json").unwrap();
    }

    /// The live cache, re-keyed by model product id.
    fn observed_cache(&self) -> BTreeMap<String, ModelEntry> {
        let model_for: BTreeMap<&String, &String> =
            self.real_ids.iter().map(|(m, r)| (r, m)).collect();
        self.dispatch
            .project_registrations
            .read()
            .unwrap()
            .iter()
            .map(|r| {
                let model = model_for
                    .get(&r.name)
                    .unwrap_or_else(|| panic!("cache shows unknown product {}", r.name));
                let entry = ModelEntry {
                    has_binding: r.has_workspace_binding,
                    setup: r.setup_state.clone(),
                };
                ((*model).clone(), entry)
            })
            .collect()
    }

    fn observed_durable(&self) -> BTreeSet<String> {
        let model_for: BTreeMap<&String, &String> =
            self.real_ids.iter().map(|(m, r)| (r, m)).collect();
        self.store
            .inner
            .list()
            .unwrap()
            .iter()
            .map(|record| (*model_for[&record.registration.product_id]).clone())
            .collect()
    }
}

// ── Replay ─────────────────────────────────────────────────────────────────

fn replay(name: &str, states: &[serde_json::Value]) {
    let mut sut = Harness::new();
    for (index, raw) in states.iter().enumerate() {
        let model = decode_state(raw);
        let product = model.last_product.as_str();
        let at = format!("{name} step {index} ({} {product})", model.last_action);
        let ok = bicameral_api::tool_request::ToolResponseStatus::Ok;

        match model.last_action.as_str() {
            "init" => {}
            "create" => {
                let response = sut.create(product);
                assert_eq!(response.status, ok, "{at}: {response:?}");
            }
            "bindAccepted" => {
                let response = sut.bind(product);
                assert_eq!(response.status, ok, "{at}: {response:?}");
            }
            "bindRejected" => {
                let response = sut.bind(product);
                assert_ne!(response.status, ok, "{at}: bind must be rejected");
            }
            "restart" => sut.restart(),
            "corruptBinding" => sut.corrupt_binding(product),
            "listFailing" | "listHealthy" => sut
                .store
                .list_fails
                .store(model.list_fails, Ordering::SeqCst),
            other => panic!("{at}: unknown action {other}"),
        }

        assert_eq!(
            sut.observed_durable(),
            model.durable,
            "{at}: durable registry"
        );
        assert_eq!(
            sut.observed_cache(),
            model.cache,
            "{at}: live registration cache"
        );
    }
}

#[test]
fn daemon_registration_cache_conforms_to_quint_model() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/product_registry_mbt");
    let mut traces: Vec<_> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("{}: {e}", dir.display()))
        .map(|entry| entry.unwrap().path())
        .filter(|path| path.to_string_lossy().ends_with(".itf.json"))
        .collect();
    traces.sort();
    assert!(!traces.is_empty(), "no traces in {}", dir.display());

    for path in traces {
        let itf: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        let states = itf["states"].as_array().expect("ITF has states");
        replay(&path.file_name().unwrap().to_string_lossy(), states);
    }
}
